<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRoute} from 'vue-router'
import {useWorkforceText} from '../text'
import {usePhasePage} from '../phasePage'
import {WorkforceApiError} from '../api'
import {emptyPoint,tomorrow,useWorkModeText,type WorkModeData,type WorkMode,type HomeAddress} from '../workMode'
import WorkModeFields from '../components/WorkModeFields.vue'
import WorkPointFields from '../components/WorkPointFields.vue'
import PhaseStatus from '../components/PhaseStatus.vue'
const {error}=useWorkforceText()
const {api,home,base,current,loading,busy,failure,notice,load}=usePhasePage(),route=useRoute(),{w}=useWorkModeText()
const pointBusy=ref(false)
const data=ref<WorkModeData|null>(null),mode=ref<WorkMode>('legacy'),inherit=ref(true),effectiveFrom=ref(''),addressDate=ref(''),point=ref(emptyPoint()),notes=ref<Record<string,string>>({})
type Pending={path:string;body:unknown};const pending=ref<Pending|null>(null)
const employeeId=String(route.params.employeeId||''),self=computed(()=>!!data.value&&home.value?.myself?.id===data.value.employeeId),minimum=computed(()=>data.value?tomorrow(data.value.serverDate):''),assignmentMinimum=computed(()=>{const dates=data.value?.assignments.map(a=>a.effectiveFrom)||[];return dates.reduce((max,d)=>d>=max?tomorrow(d):max,minimum.value)})
function refresh(){void load(()=>api().get<WorkModeData>(employeeId?`/employees/${encodeURIComponent(employeeId)}/work-mode`:'/work-mode'),v=>{data.value=v;if(!effectiveFrom.value||effectiveFrom.value<assignmentMinimum.value)effectiveFrom.value=assignmentMinimum.value;if(!addressDate.value||addressDate.value<minimum.value)addressDate.value=minimum.value})}
async function send(command?:Pending){if(busy.value||(!pending.value&&!command))return;if(!pending.value)pending.value=JSON.parse(JSON.stringify(command));busy.value=true;failure.value='';notice.value='';try{await api().put(pending.value!.path,pending.value!.body);if(!current())return;pending.value=null;notice.value=w('saved');refresh()}catch(e){if(!current())return;if(e instanceof WorkforceApiError&&e.status>=400&&e.status<500)pending.value=null;failure.value=error(e)}finally{if(current())busy.value=false}}
function saveMode(){if(!data.value?.canManage||pending.value)return;if(effectiveFrom.value<assignmentMinimum.value){failure.value=w('invalidDate');return}void send({path:`/employees/${encodeURIComponent(data.value.employeeId)}/work-modes/${crypto.randomUUID()}`,body:{expectedVersion:Math.max(0,...data.value.assignments.map(a=>a.version)),effectiveFrom:effectiveFrom.value,mode:mode.value,inheritPosition:inherit.value}})}
function applyAddress(){if(!self.value||pending.value||pointBusy.value)return;if(addressDate.value<minimum.value){failure.value=w('invalidDate');return}void send({path:`/home-addresses/${crypto.randomUUID()}`,body:{point:point.value,effectiveFrom:addressDate.value}})}
function selfReview(a:HomeAddress){return self.value||a.applicantId===home.value?.myself?.accountId}
function decide(a:HomeAddress,status:'approved'|'rejected'){if(!data.value?.canReview||selfReview(a)||a.status!=='pending'||pending.value||!notes.value[a.id]?.trim()||notes.value[a.id]!.trim().length>500||(status==='approved'&&a.effectiveFrom<minimum.value))return;void send({path:`/home-addresses/${encodeURIComponent(a.id)}/decision`,body:{expectedVersion:a.version,status,note:notes.value[a.id]!.trim()}})}
onMounted(refresh)
</script>
<template><section class="wf-panel wf-form-panel"><header class="wf-toolbar"><h2>{{w('title')}}<span v-if="data"> · {{data.employeeName}}</span></h2><button :disabled="busy||loading||pointBusy||!!pending" @click="refresh">{{w('refresh')}}</button></header><div class="wf-inline"><RouterLink v-if="home?.employeeManage" :to="base+'/management'">{{w('back')}}</RouterLink><RouterLink v-if="employeeId" :to="base+'/employees'">{{w('backEmployees')}}</RouterLink><RouterLink v-else :to="base+'/clock'">{{w('backClock')}}</RouterLink></div><PhaseStatus :failure="failure" :notice="notice" :loading="loading"/><div v-if="pending" role="status"><p>{{w('unknown')}}</p><button :disabled="busy" @click="send()">{{w('retry')}}</button></div><template v-if="data&&!loading"><p class="wf-hint">{{w('nextDay')}}</p><p v-if="data.policy">{{w('mode')}}: {{w(data.policy.mode)}}</p><form v-if="data.canManage" @submit.prevent="saveMode"><fieldset :disabled="busy||!!pending"><legend>{{w('personal')}}</legend><label class="wf-check"><input v-model="inherit" type="checkbox">{{w('inherit')}}</label><WorkModeFields v-if="!inherit" v-model="mode"/><label>{{w('effectiveFrom')}}<input v-model="effectiveFrom" type="date" :min="assignmentMinimum" required></label><button class="primary">{{w('save')}}</button></fieldset></form><h3>{{w('history')}}</h3><div class="wf-table-wrap"><table><thead><tr><th>{{w('effectiveFrom')}}</th><th>{{w('mode')}}</th><th>{{w('source')}}</th><th>{{w('version')}}</th></tr></thead><tbody><tr v-for="a in data.assignments" :key="a.id"><td>{{a.effectiveFrom}}</td><td>{{w(a.mode)}}</td><td>{{w(a.origin==='position'?'position':'personal')}}<small v-if="a.positionId"> · {{a.positionId}} / {{a.positionVersion}}</small></td><td>{{a.version}}</td></tr><tr v-if="!data.assignments.length"><td colspan="4">{{w('empty')}}</td></tr></tbody></table></div><form v-if="self" @submit.prevent="applyAddress"><fieldset :disabled="busy||!!pending"><legend>{{w('address')}}</legend><WorkPointFields :point="point" @locating="pointBusy=$event"/><label>{{w('effectiveFrom')}}<input v-model="addressDate" type="date" :min="minimum" required></label><button class="primary" :disabled="pointBusy">{{w('submit')}}</button></fieldset></form><h3>{{w('addresses')}}</h3><p v-if="!data.addresses.length" class="wf-empty">{{w('empty')}}</p><article v-for="a in data.addresses" :key="a.id" class="wf-section"><h4>{{a.point.label}} · {{w(a.status)}}</h4><p>{{a.point.latitude}}, {{a.point.longitude}} · {{a.point.radiusMeters}} m · {{a.effectiveFrom}}</p><p v-if="a.reviewerId">{{w('reviewer')}}: {{a.reviewerId}}</p><p v-if="a.reviewNote">{{w('reviewNote')}}: {{a.reviewNote}}</p><p v-if="a.status==='pending'&&selfReview(a)">{{w('selfReview')}}</p><div v-else-if="a.status==='pending'&&data.canReview"><label>{{w('note')}}<input v-model="notes[a.id]" maxlength="500" required :disabled="busy||!!pending"></label><div class="wf-inline"><button :disabled="busy||!!pending||!notes[a.id]?.trim()||notes[a.id]!.trim().length>500||a.effectiveFrom<minimum" @click="decide(a,'approved')">{{w('approve')}}</button><button :disabled="busy||!!pending||!notes[a.id]?.trim()||notes[a.id]!.trim().length>500" @click="decide(a,'rejected')">{{w('reject')}}</button></div><p v-if="a.effectiveFrom<minimum" class="wf-hint">{{w('nextDay')}}</p></div></article></template></section></template>





